import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Infrastructure Terraform Specification","description":"","frontmatter":{},"headers":[],"relativePath":"specs/infra-terraform.md","filePath":"specs/infra-terraform.md","lastUpdated":1786319962000}`),a={name:`specs/infra-terraform.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /specs/infra-terraform.md for this page in Markdown format</div><h1 id="infrastructure-terraform-specification" tabindex="-1">Infrastructure Terraform Specification <a class="header-anchor" href="#infrastructure-terraform-specification" aria-label="Permalink to “Infrastructure Terraform Specification”">​</a></h1><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to “Scope”">​</a></h2><p>Terraform provisions the durable Cloudflare resources the workers consume. It does not manage workers. See <a href="/adr/002-terraform-wrangler-boundary">ADR-002</a> for the decision.</p><table tabindex="0"><thead><tr><th>Owned by Terraform</th><th>Owned by Wrangler</th></tr></thead><tbody><tr><td><code>cloudflare_hyperdrive_config</code> × 2/env</td><td>Worker names, code, versions, deployments</td></tr><tr><td><code>cloudflare_r2_bucket</code> + <code>_cors</code> (opt-in)</td><td>Routes, custom domains, service bindings, vars, secrets, assets</td></tr></tbody></table><p>The uploads bucket carries its own CORS policy: browsers reject a presigned <code>PUT</code> to a bucket without one, so the policy belongs with the Terraform-owned bucket rather than as a dashboard step. It allows <code>PUT</code> with <code>Content-Type</code> from <code>uploads_cors_origins</code>, which must be explicit – a <code>*</code> origin is rejected at plan time.</p><p><strong>Invariant:</strong> no field is configured by both tools. The only values crossing the boundary are stable, non-secret resource identifiers – the two Hyperdrive IDs, plus the R2 bucket name when uploads are enabled.</p><p><strong>Non-goals:</strong> worker deployment, DNS, multi-region orchestration, blue-green deploys, autoscaling.</p><h2 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to “Layout”">​</a></h2><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">infra/</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  modules/cloudflare/</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">   # Resources, connection parsing, naming</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  envs/</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">{staging,production}</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/</span></span></code></pre></div><p>One root per environment, one HCP Terraform workspace per root. Each root hard-codes its own <code>environment</code>, so no state can create another environment&#39;s resources.</p><p>There is no <code>dev</code> root. Local development uses <code>CLOUDFLARE_HYPERDRIVE_LOCAL_CONNECTION_STRING_&lt;BINDING&gt;</code> and provisions nothing.</p><p>There is no <code>preview</code> root either. A single shared preview environment is not per-PR isolation – concurrent pull requests would overwrite each other&#39;s deployment and share one database – and it duplicates staging&#39;s role. Add an environment by copying a root and adding a matching <code>wrangler.jsonc</code> block.</p><h2 id="versions" tabindex="-1">Versions <a class="header-anchor" href="#versions" aria-label="Permalink to “Versions”">​</a></h2><table tabindex="0"><thead><tr><th>Component</th><th>Constraint</th></tr></thead><tbody><tr><td>terraform</td><td><code>&gt;= 1.12, &lt; 2</code></td></tr><tr><td>cloudflare</td><td><code>~&gt; 5.0</code></td></tr></tbody></table><p>Version constraints live in env roots; the module declares <code>source</code> only. Lock files are committed and cover linux, macOS and Windows.</p><h2 id="hyperdrive" tabindex="-1">Hyperdrive <a class="header-anchor" href="#hyperdrive" aria-label="Permalink to “Hyperdrive”">​</a></h2><p>Two configurations per environment, matching the two bindings in <code>apps/api/</code>:</p><table tabindex="0"><thead><tr><th>Name</th><th><code>caching.disabled</code></th><th>Binding</th></tr></thead><tbody><tr><td><code>&lt;slug&gt;-&lt;env&gt;-cached</code></td><td><code>false</code></td><td><code>HYPERDRIVE_CACHED</code></td></tr><tr><td><code>&lt;slug&gt;-&lt;env&gt;-uncached</code></td><td><code>true</code></td><td><code>HYPERDRIVE_UNCACHED</code></td></tr></tbody></table><p><code>cache_max_age_seconds</code> (60) and <code>cache_stale_while_revalidate_seconds</code> (15) are set explicitly rather than inherited, so the staleness window is reviewable in the configuration.</p><p><code>origin_connection_limit</code> is a soft maximum per configuration – Cloudflare may briefly exceed it. It defaults to 20, Cloudflare&#39;s ceiling on the Workers Free plan and low enough that both configurations together stay within a small Neon compute&#39;s <code>max_connections</code>. Both env roots expose it so it can be raised per deployment; the origin sees twice the value.</p><h3 id="connection-url" tabindex="-1">Connection URL <a class="header-anchor" href="#connection-url" aria-label="Permalink to “Connection URL”">​</a></h3><p><code>database_url</code> is split by one anchored regex into the discrete fields Hyperdrive stores. Accepted shape:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>postgres[ql]://USER:PASSWORD@HOST[:PORT]/DATABASE[?params]</span></span></code></pre></div><p>The port defaults to <code>5432</code>; query parameters are ignored, since TLS to the origin is Hyperdrive&#39;s setting rather than the client&#39;s.</p><p>Three failures are rejected at plan time rather than surfacing later as connection errors:</p><table tabindex="0"><thead><tr><th>Rejected</th><th>Why</th></tr></thead><tbody><tr><td>Malformed URL</td><td>Nothing to parse.</td></tr><tr><td>Percent-encoded credentials</td><td>Terraform has no <code>urldecode</code>, so the escape sequence would be stored verbatim.</td></tr><tr><td>A <code>-pooler</code> host</td><td>Hyperdrive is the pool; stacking two exhausts connections.</td></tr></tbody></table><h2 id="state" tabindex="-1">State <a class="header-anchor" href="#state" aria-label="Permalink to “State”">​</a></h2><p>HCP Terraform, via a <code>cloud</code> block – state, locking and version history in one place, with no bucket to provision first. See <a href="/adr/003-hcp-terraform-state">ADR-003</a>.</p><p>Each root declares an empty <code>cloud {}</code> block. The organization and existing workspace are selected with <code>TF_CLOUD_ORGANIZATION</code> and <code>TF_WORKSPACE</code>, so a fork carries no one else&#39;s deployment targets.</p><p>Workspace names must end in <code>-staging</code> or <code>-production</code>. Each root asserts the suffix in an output <code>precondition</code>, failing at plan time otherwise. The reason is that <code>TF_WORKSPACE</code> selects the state while the directory selects only the resource names, and an exported <code>TF_WORKSPACE</code> takes precedence over the value in <code>.env.terraform.&lt;env&gt;.local</code> – Bun&#39;s <code>--env-file</code> does not overwrite variables already present in the environment. Unguarded, a stale export would point the staging root at production state, where it would rename the Hyperdrive configurations and invalidate their IDs.</p><p>The check runs wherever the configuration is evaluated – <code>plan</code>, <code>apply</code>, <code>destroy</code>, and <code>validate</code>. It does not run for <code>import</code> or the <code>state</code> subcommands, which write state without consulting the configuration, nor for <code>output</code>, which returns values already stored in state rather than recomputing them. <code>output</code> is the consequential one: it can print another environment&#39;s Hyperdrive IDs for pasting into a <code>wrangler.jsonc</code>, wiring a worker to the wrong database without touching state. The gap is inherent to Terraform, so it is documented and paired with a <code>workspace show</code> step rather than worked around.</p><p>Terraform is invoked through two package scripts, <code>infra:staging</code> and <code>infra:production</code>, which load the matching env file and forward all arguments. Calling <code>terraform</code> directly skips workspace selection.</p><p>Each workspace must also set <strong>Terraform Working Directory</strong> to <code>envs/&lt;env&gt;</code>. Remote runs upload the configuration, and a root referencing <code>../../modules/cloudflare</code> reaches outside its own directory; Terraform uploads parent directories only when a working directory is set, to the depth of that setting. There is no <code>cloud</code> block argument for it, so it is the one workspace setting the repository cannot declare.</p><p><strong>State is credential-bearing.</strong> Hyperdrive stores the origin password as a discrete field, so it is written to state. <code>sensitive = true</code> hides values from output; it does not encrypt them. HCP Terraform encrypts state at rest and retains every version.</p><h2 id="credentials" tabindex="-1">Credentials <a class="header-anchor" href="#credentials" aria-label="Permalink to “Credentials”">​</a></h2><p>Runs execute in HCP Terraform, so values come from workspace variables rather than a developer&#39;s shell.</p><table tabindex="0"><thead><tr><th>Kind</th><th>Supplied as</th></tr></thead><tbody><tr><td>Cloudflare provider</td><td><code>CLOUDFLARE_API_TOKEN</code> workspace environment var</td></tr><tr><td>Origin database</td><td><code>database_url</code> workspace variable, sensitive</td></tr><tr><td>Application secrets</td><td><code>wrangler secret put</code> – never Terraform</td></tr></tbody></table><p>The Cloudflare token needs <strong>Account → Hyperdrive → Edit</strong>, plus <strong>Account → Workers R2 Storage → Edit</strong> only when the uploads bucket is enabled. It needs no zone or worker scopes.</p><p>The infrastructure workflow holds one credential: <code>TF_API_TOKEN</code>, an HCP Terraform team token. Terraform&#39;s Cloudflare and database credentials are never stored in GitHub. The separate worker-deploy workflow does hold a <code>CLOUDFLARE_API_TOKEN</code> – Cloudflare&#39;s <strong>Edit Cloudflare Workers</strong> template, which grants the worker, route and DNS scopes Terraform deliberately lacks.</p><p>Setting a workspace&#39;s execution mode to <strong>Local</strong> stores state remotely but runs Terraform on the caller&#39;s machine; HCP then ignores workspace variables, so values come from <code>TF_VAR_*</code> or a gitignored <code>terraform.tfvars</code>.</p><h2 id="naming" tabindex="-1">Naming <a class="header-anchor" href="#naming" aria-label="Permalink to “Naming”">​</a></h2><p>Resource values use <code>{project_slug}-{environment}[-role]</code>, lowercase <code>^[a-z0-9-]+$</code>. <code>project_slug</code> must match the worker name prefix in <code>apps/*/wrangler.jsonc</code>.</p><p>Resource identifiers name the concrete thing (<code>cloudflare_hyperdrive_config.cached</code>); module names describe the architectural role (<code>module.edge</code>).</p><h2 id="ci" tabindex="-1">CI <a class="header-anchor" href="#ci" aria-label="Permalink to “CI”">​</a></h2><p><code>.github/workflows/ci.yml</code> runs <code>terraform fmt -check</code> and <code>terraform validate</code> on every push. Because <code>init -backend=false</code> still initializes an HCP <code>cloud {}</code> block, CI validates a disposable copy with that block removed and a correctly suffixed local workspace. No HCP or Cloudflare credentials are needed.</p><p><code>.github/workflows/infra.yml</code> plans and applies, on manual dispatch only, serialised per environment and gated by GitHub Environment reviewers. Application deploys never run Terraform.</p>`,47)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};